Translate the following GNU C++0x code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstdint>
using namespace std;

using i128 = __int128_t;

i128 gcd(i128 a, i128 b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    long long best_num = 0, best_den = 1;
    double min_err = numeric_limits<double>::infinity();

    for (long long d = 1; d <= n; ++d) {
        long long num1 = 0;
        long long lo = 0, hi = 100000;
        while (lo <= hi) {
            long long mid = (lo + hi) / 2;
            if (static_cast<i128>(mid) * y <= static_cast<i128>(x) * d) {
                num1 = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        long long num2 = 0;
        lo = 0, hi = 100000;
        while (lo <= hi) {
            long long mid = (lo + hi) / 2;
            if (static_cast<i128>(mid) * y < static_cast<i128>(x) * d) {
                lo = mid + 1;
            } else {
                num2 = mid;
                hi = mid - 1;
            }
        }

        double err1 = fabs(static_cast<double>(num1) / d - static_cast<double>(x) / y);
        double err2 = fabs(static_cast<double>(num2) / d - static_cast<double>(x) / y);

        long long chosen_num = num1;
        long long chosen_den = d;
        double chosen_err = err1;

        if (err2 < err1 - 1e-15) {
            chosen_num = num2;
            chosen_den = d;
            chosen_err = err2;
        }

        long long g = gcd(chosen_num, chosen_den);
        chosen_num /= g;
        chosen_den /= g;

        if (chosen_err < min_err) {
            best_num = chosen_num;
            best_den = chosen_den;
            min_err = chosen_err;
        }
    }

    cout << best_num << "/" << best_den << endl;
    return 0;
}
